            return
        }
        // ⌘ suppresses snapping while the drag is in flight, not only at the
        // press; the candidate list the gesture fetched is kept.
        snapper = CanvasSnapper(
            xs: snapper.xs, ys: snapper.ys,
            threshold: CanvasSnapper.tick(canvasDistance(CanvasSnapper.threshold)),
            enabled: snappingEnabled && !flags.contains(.command))
        let canvasPoint = viewToCanvas(point)
        if var session = moving {
            session.update(point: canvasPoint, snapper: snapper)
            moving = session
            onLiveUpdate?(session.ops(to: gestureTarget))
        } else if var session = scaling {
            session.update(
                point: canvasPoint, aspectFree: flags.contains(.shift),
                aboutCentre: flags.contains(.option))
            scaling = session
            onLiveUpdate?(session.ops(to: gestureTarget))
        } else if var session = rotating {
            session.update(point: canvasPoint, snapping: flags.contains(.shift))
            rotating = session
            onLiveUpdate?([session.op(to: gestureTarget)])
        } else if var session = cropping {
            session.update(point: canvasPoint)
            cropping = session
            onLiveUpdate?([session.op(to: gestureTarget)])
        } else if var session = endpointDrag {
            guard let box = box(for: session.clip) else { return }
            session.update(unit: box.endpointUnit(canvasPoint))
            endpointDrag = session
            onLiveUpdate?([session.op])
        } else if obscureDrag != nil {
            continueObscureDrag(at: canvasPoint, flags: flags)
        }
        overlay.needsDisplay = true
    }

    /// Mouse-up. Closes the live edit as ONE undo step (§7.6); a gesture that
    /// changed nothing registers none, because `endLiveEdit` compares handles.
    func endGesture(at point: CGPoint, flags: NSEvent.ModifierFlags) {
        if panning != nil {
            panning = nil
        } else if moving != nil {
            moving = nil
            onLiveEnd?("Move")
        } else if scaling != nil {
            scaling = nil
            onLiveEnd?("Scale")
        } else if rotating != nil {
            rotating = nil
            onLiveEnd?("Rotate")
        } else if cropping != nil {
            cropping = nil
            onLiveEnd?("Crop")
        } else if endpointDrag != nil {
            endpointDrag = nil
            onLiveEnd?("Move Endpoint")
        } else if let session = obscureDrag {
            obscureDrag = nil
            onLiveEnd?(session.undoName)
        }
        overlay.needsDisplay = true
        window?.invalidateCursorRects(for: overlay)
    }

    /// Double-click: a text clip opens its inline editor, anything with pixels
    /// enters crop mode (spec §4.2).
    private func doubleClicked(_ id: UInt32) {
        guard let clip = snapshot.clip(id) else { return }
        if clip.text != nil, case .text = clip.source {
            beginTextEditing(id)
            return
        }
        if setCropMode(true) { return }
        NSSound.beep()
    }

    private func beginMove(anchor: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
        let ids = selection.contains(anchor) ? selection : [anchor]
        var bases: [UInt32: CGPoint] = [:]
        gestureTarget = editTarget
        for id in ids {
            guard let clip = snapshot.clip(id),
                  snapshot.track(clip.track)?.locked != true
            else { continue }
            let props = gestureTarget.start(of: clip, in: project).video
            bases[id] = CGPoint(x: props.x, y: props.y)
        }
        guard !bases.isEmpty, let box = box(for: anchor) else { return }
        snapper = makeSnapper(excluding: Set(bases.keys), suppressed: flags.contains(.command))
        moving = CanvasMoveSession(
            bases: bases, anchor: anchor, anchorBounds: box.bounds, grab: viewToCanvas(point))
        onLiveBegin?()
    }

    private func beginScale(_ id: UInt32, handle: CanvasHandle) {
        guard let box = box(for: id), let clip = snapshot.clip(id) else { return }
        let route = editTarget.forScale(of: clip)
        gestureTarget = route
        let start = route.start(of: clip, in: project)
        let base = start.video
        let rect = startRect(of: box, base: base)
        let target: CanvasScaleTarget
        if let shape = clip.shape, case .shape = clip.source {
            target = .box(shape.boxSize)
        } else if clip.text != nil, case .text = clip.source {
            // An auto-sized text clip has no stored width, so the measured box
            // (divided back out of the scale) is the width the drag starts from.
            target = .textWidth(
                start.text?.width ?? (Double(rect.width) / max(base.scale, 0.001)))
        } else {
            target = .uniform
        }
        scaling = CanvasScaleSession(
            clip: id, handle: handle, target: target, base: base, startRect: rect,
            rotation: base.rotation, scale: base.scale,
            boxSize: clip.shape?.boxSize ?? .zero, textWidth: start.text?.width ?? 0)
        onLiveBegin?()
    }

    private func beginRotate(_ id: UInt32, at point: CGPoint) {
        guard let clip = snapshot.clip(id) else { return }
        gestureTarget = editTarget
        let base = gestureTarget.start(of: clip, in: project).video
        let anchor = canvasAnchor(of: clip, in: snapshot.canvas, video: base)
        rotating = CanvasRotateSession(
            clip: id, base: base, anchor: anchor,
            grabAngle: CanvasRotateSession.angle(of: viewToCanvas(point), about: anchor),
            rotation: base.rotation)
        onLiveBegin?()
    }

    private func beginCrop(_ id: UInt32, handle: CanvasHandle) {
        guard let box = box(for: id), let clip = snapshot.clip(id) else { return }
        gestureTarget = editTarget
        let base = gestureTarget.start(of: clip, in: project).video
        cropping = CanvasCropSession(
            clip: id, handle: handle, base: base, sourceSize: box.sourceSize,
            startRect: startRect(of: box, base: base), rotation: base.rotation, crop: base.crop)
        onLiveBegin?()
    }

    private func beginEndpoint(_ id: UInt32, endpoint: CanvasEndpoint) {
        guard let clip = snapshot.clip(id), let shape = clip.shape else { return }
        endpointDrag = CanvasEndpointSession(
            clip: id, endpoint: endpoint,
            unit: endpoint == .from ? shape.fromPoint : shape.toPoint)
        onLiveBegin?()
    }

    /// The uncropped rectangle a session starts from, computed from the
    /// target's props (what the op merges into, CI-13) rather than the
    /// recipe's evaluated ones — the two differ only once a clip has actions.
    private func startRect(of box: CanvasLayerBox, base: VideoProps) -> CGRect {
        canvasRect(
            of: box.clip, in: snapshot.canvas, sourceSize: box.sourceSize, video: base.uncropped)
    }

    // MARK: - Keyboard

    /// The keys the canvas owns while it holds first responder. Everything
    /// else returns false and walks the responder chain to
    /// `EditorViewController.keyDown` (the bare-key transport map).
    func handleKey(_ event: NSEvent) -> Bool {
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard flags.subtracting(.shift).isEmpty else { return false }
        switch event.keyCode {
        case 53:  // Esc
            if cancelGesture() { return true }
            guard cropMode else { return false }
            setCropMode(false)
            return true
        case 36, 76:  // Return, keypad Enter
            guard cropMode else { return false }
            setCropMode(false)
            return true
        case 49:  // Space — armed for panning; the tap is settled on key-up.
            guard !event.isARepeat else { return true }
            spaceHeld = true
            spaceDidPan = false
            return true
        default:
            break
        }
        let step = flags.contains(.shift) ? Self.nudgeStepLarge : Self.nudgeStep
        switch event.keyCode {
        case 123: return nudge(dx: -step, dy: 0)
        case 124: return nudge(dx: step, dy: 0)
        case 125: return nudge(dx: 0, dy: step)
        case 126: return nudge(dx: 0, dy: -step)
        default: return false
        }
    }

    /// Focus left the canvas with Space still down (the inline text editor
    /// taking over, a click in the timeline). Without this the pan stays armed
    /// and the next canvas click drags the whole canvas instead of a clip.
    func releaseSpace() {
        spaceHeld = false
        spaceDidPan = false
    }

    func handleKeyUp(_ event: NSEvent) -> Bool {
        guard event.keyCode == 49 else { return false }
        spaceHeld = false
        // A Space that never panned is the transport's, and the editor never
        // saw the key-down because this view swallowed it.
        if !spaceDidPan { onSpaceTapped?() }
        spaceDidPan = false
        return true
    }

    /// Arrow-key nudge (spec §4.2). One op per clip and one undo step, the
    /// same shape a move drag commits.
    @discardableResult
    func nudge(dx: CGFloat, dy: CGFloat) -> Bool {
        var ops: [ReelOp] = []
        for id in selection.sorted() {
            guard let clip = snapshot.clip(id), snapshot.track(clip.track)?.locked != true
            else { continue }
            let props = editTarget.start(of: clip, in: project).video
            ops.append(
                editTarget.op(
                    video: VideoPatch(
                        x: canvasRound(props.x + Double(dx)),
                        y: canvasRound(props.y + Double(dy))),
                    clip: id))
        }
        guard !ops.isEmpty else { return false }
        onEdit?("Nudge", ops)
        return true
    }

    /// Esc during a drag: abandons the session without committing. The live
    /// edit still has to be closed, or the document keeps its gesture base
    /// forever and the next edit merges into it.
    private func cancelGesture() -> Bool {
        guard moving != nil || scaling != nil || rotating != nil || cropping != nil
            || endpointDrag != nil || obscureDrag != nil
        else { return false }
        moving = nil
        scaling = nil
        rotating = nil
        cropping = nil
        endpointDrag = nil
        obscureDrag = nil
        onLiveCancel?()
        overlay.needsDisplay = true
        return true
    }

    // MARK: - Zoom and pan from the trackpad

    func pinched(by magnification: CGFloat) {
        pinchAccumulator += magnification
        while abs(pinchAccumulator) >= Self.pinchStep {
            let direction = pinchAccumulator > 0 ? 1 : -1
            pinchAccumulator -= CGFloat(direction) * Self.pinchStep
            onZoomStep?(direction)
        }
    }

    func scrolled(dx: CGFloat, dy: CGFloat) {
        guard canPan else { return }
        panOffset = CGPoint(x: panOffset.x + dx, y: panOffset.y + dy)
        layoutCanvas()
        overlay.needsDisplay = true
    }

    // MARK: - Inline text editing (spec §4.2)

    /// An `NSTextView` positioned in canvas space over the text clip. It is
    /// axis-aligned even for a rotated clip: AppKit text editing in a rotated

        guard let document = document else { return }
        if !ids.isEmpty { inspector?.clipPicked() }
        guard document.selection != ids else { return }
        document.selection = ids
        viewStateDidChange()
    }

    /// Pinch and ⌥-wheel walk the same four stops as the toolbar popup, so the
    /// popup can never show a zoom the canvas is not at.
    private func canvasZoomStepped(_ delta: Int) {
        if delta > 0 {
            zoomIn(nil)
        } else {
            zoomOut(nil)
        }
    }

    /// Crop mode is view state on the canvas — no op runs and no undo step is
    /// registered — so it travels on the one document channel, the same way
    /// selection does. The inspector's Crop section (M2) reads it from there.
    private func canvasCropModeChanged() {
        viewStateDidChange()
    }

    // MARK: - Commands

    /// C, and the Crop section's Crop on Canvas button (spec §4.2, §9).
    /// Refuses with nothing selected rather than entering a mode with no box in it.
    func toggleCanvasCropMode() {
        guard let canvas = previewCanvas else {
            NSSound.beep()
            return
        }
        if !canvas.setCropMode(!canvas.cropMode) { NSSound.beep() }
    }

    // MARK: - Validation

    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the other answers alone; `item` is passed so the check
    /// mark can be set beside the answer, as the base file does for its own.
    func validateCanvasAction(
        _ action: Selector, item: any NSValidatedUserInterfaceItem
    ) -> Bool? {
        guard let document = document else { return false }
        switch action {
        case #selector(toggleCropMode(_:)):
            (item as? NSMenuItem)?.state = previewCanvas?.cropMode == true ? .on : .off
            return !document.selection.isEmpty
        default:
            return nil
        }
    }
}
import AppKit

/// The preview canvas's geometry and its gesture sessions (spec §4.2).
///
/// Everything here works in CANVAS space — pixels, origin at the canvas's
/// top-left, **y growing downward** — which is the space `canvasRect(of:in:
/// sourceSize:video:)` and `canvasAnchor(of:in:video:)` in
/// `ProjectSnapshot.swift` speak, and the space the frame recipe describes.
/// `PreviewCanvasView` owns the one conversion to and from view points
/// (`canvasToView` / `viewToCanvas`, mapped through `AVPlayerLayer.videoRect`
/// so handles and pixels cannot drift); nothing in this file knows about
/// points, zoom or panning.
///
/// **The pitfall this file exists to avoid:** placement is *not*
/// re-derivable. Cropping removes edges in place and rotation happens about
/// the *uncropped* centre, so every rectangle comes from `canvasRect` and
/// every rotation from `canvasAnchor` — never from a hand-rolled transform.

// MARK: - Rotation

/// Rotates `vector` by `degrees`. Canvas y grows downward, so a positive
/// angle reads CLOCKWISE on screen — the same sense the canvas's hit boxes
/// (`CanvasLayerBox`) un-rotate by, which is what keeps overlay hit-testing
/// and the compositor's picture the same answer.
func canvasRotate(_ vector: CGVector, degrees: Double) -> CGVector {
    guard degrees != 0 else { return vector }
    let radians = degrees * .pi / 180
    let c = cos(radians)
    let s = sin(radians)
    return CGVector(dx: vector.dx * c - vector.dy * s, dy: vector.dx * s + vector.dy * c)
}

/// The inverse of `canvasRotate` — a canvas point taken back into the
/// layer's own axis-aligned space.
func canvasUnrotate(_ vector: CGVector, degrees: Double) -> CGVector {
    canvasRotate(vector, degrees: -degrees)
}

// MARK: - Handles

/// One of the eight scale handles of a selection box, named for where it
/// sits in the layer's OWN (un-rotated) canvas rect. The canvas is y-down,
/// so "top" is the smaller y — exactly what it looks like on screen.
enum CanvasHandle: CaseIterable {
    case topLeft
    case top
    case topRight
    case right
    case bottomRight
    case bottom
    case bottomLeft
    case left

    /// Position in the unit square measured from the rect's centre: -1, 0 or
    /// +1 on each axis.
    var unit: CGPoint {
        switch self {
        case .topLeft: return CGPoint(x: -1, y: -1)
        case .top: return CGPoint(x: 0, y: -1)
        case .topRight: return CGPoint(x: 1, y: -1)
        case .right: return CGPoint(x: 1, y: 0)
        case .bottomRight: return CGPoint(x: 1, y: 1)
        case .bottom: return CGPoint(x: 0, y: 1)
        case .bottomLeft: return CGPoint(x: -1, y: 1)
        case .left: return CGPoint(x: -1, y: 0)
        }
    }

    /// The handle across the box — the point a plain (no-⌥) scale drag pins.
    var opposite: CanvasHandle {
        switch self {
        case .topLeft: return .bottomRight
        case .top: return .bottom
        case .topRight: return .bottomLeft
        case .right: return .left
        case .bottomRight: return .topLeft
        case .bottom: return .top
        case .bottomLeft: return .topRight
        case .left: return .right
        }
    }

    /// Corners drive both axes; edge midpoints drive one.
    var isCorner: Bool { unit.x != 0 && unit.y != 0 }
    var drivesX: Bool { unit.x != 0 }
    var drivesY: Bool { unit.y != 0 }

    /// Where the handle sits on `rect`, in the rect's own (un-rotated) space.
    func point(in rect: CGRect) -> CGPoint {
        CGPoint(
            x: rect.midX + unit.x * rect.width / 2,
            y: rect.midY + unit.y * rect.height / 2)
    }

    /// AppKit has no diagonal resize cursor in its public API, so corners get
    /// the crosshair rather than a cursor that lies about the axis.
    var cursor: NSCursor {
        if isCorner { return .crosshair }
        return drivesX ? .resizeLeftRight : .resizeUpDown
    }
}

/// Which end of a `line` / `arrow` shape a drag grabbed (spec §4.2's
/// endpoint handles). Distinct from `TimelineEdge`, which is a *time* edge.
enum CanvasEndpoint: Equatable {
    case from
    case to
}

/// What is under the pointer on the canvas. Computed once per press by
            guard let resolved = size, resolved.width > 0, resolved.height > 0 else { return nil }
            return CanvasLayerBox(
                clip: clip, canvas: snapshot.canvas, video: clip.videoProps, sourceSize: resolved,
                locked: snapshot.track(clip.track)?.locked ?? false)
        }
    }
}

// MARK: - Snapping

/// Spec §4.2's canvas snapping: the canvas centre lines, its edges, its
/// thirds, and every other visible layer's edges and centres.
///
/// The candidates are computed here in Swift from the layer rects — the core
/// has no idea where anything sits on screen — but the nearest-within-
/// threshold *pick* is `ReelSnap.resolve` (i.e. `rc_snap_resolve`), so the
/// canvas and the timeline snap by the same rule. That function speaks in
/// `Ticks`, so canvas coordinates are rounded to whole pixels on the way in;
/// a snap is always to a pixel, which is what the guides promise anyway.
struct CanvasSnapper {
    /// Grab radius in VIEW points, converted to canvas pixels per zoom.
    static let threshold: CGFloat = 8

    let xs: [Ticks]
    let ys: [Ticks]
    /// The radius in canvas pixels at the current zoom.
    let threshold: Ticks
    /// Folds together the N toggle and the ⌘ suppression, so no session ever
    /// looks at modifier flags itself.
    let enabled: Bool

    /// What a proposed rectangle has to move by to sit on a candidate, plus
    /// the guide lines to draw (canvas coordinates, nil when nothing snapped).
    struct Result {
        var offset = CGVector.zero
        var guideX: CGFloat?
        var guideY: CGFloat?
    }

    /// Tries the rectangle's leading edge, centre and trailing edge on each
    /// axis and takes the smallest correction of the three.
    func resolve(rect: CGRect) -> Result {
        var result = Result()
        guard enabled else { return result }
        if let hit = best(of: [rect.minX, rect.midX, rect.maxX], in: xs) {
            result.offset.dx = hit.delta
            result.guideX = hit.guide
        }
        if let hit = best(of: [rect.minY, rect.midY, rect.maxY], in: ys) {
            result.offset.dy = hit.delta
            result.guideY = hit.guide
        }
        return result
    }

    private func best(
        of anchors: [CGFloat], in candidates: [Ticks]
    ) -> (delta: CGFloat, guide: CGFloat)? {
        var winner: (delta: CGFloat, guide: CGFloat)?
        for anchor in anchors {
            let (resolved, snapped) = ReelSnap.resolve(
                candidates, CanvasSnapper.tick(anchor), threshold: threshold)
            guard snapped else { continue }
            let delta = CGFloat(resolved) - anchor
            if let current = winner, abs(current.delta) <= abs(delta) { continue }
            winner = (delta, CGFloat(resolved))
        }
        return winner
    }

    /// A canvas coordinate as a whole pixel, clamped well inside `Int64` so a
    /// runaway drag cannot trap the conversion.
    static func tick(_ value: CGFloat) -> Ticks {
        guard value.isFinite else { return 0 }
        return Ticks(min(max(value.rounded(), -1e9), 1e9))
    }

    /// Canvas landmarks plus the other layers'. `excluding` is the clips the
    /// gesture is moving — a drag must not snap to itself.
    static func candidates(
        boxes: [CanvasLayerBox], excluding: Set<UInt32>, canvas: CanvasSnapshot
    ) -> (xs: [Ticks], ys: [Ticks]) {
        let width = CGFloat(canvas.width)
        let height = CGFloat(canvas.height)
        var xs: Set<Ticks> = [
            tick(0), tick(width / 3), tick(width / 2), tick(width * 2 / 3), tick(width),
        ]
        var ys: Set<Ticks> = [
            tick(0), tick(height / 3), tick(height / 2), tick(height * 2 / 3), tick(height),
        ]
        for box in boxes where !excluding.contains(box.id) {
            let bounds = box.bounds
            xs.formUnion([tick(bounds.minX), tick(bounds.midX), tick(bounds.maxX)])
            ys.formUnion([tick(bounds.minY), tick(bounds.midY), tick(bounds.maxY)])
        }
        return (xs.sorted(), ys.sorted())
    }
}

/// Trims a canvas coordinate to three decimals before it goes into an op.
/// Snapping produces whole or half pixels; this only keeps float noise out of
/// the project JSON, where it would make two identical edits compare unequal.
func canvasRound(_ value: Double) -> Double {
    guard value.isFinite else { return 0 }
    return (value * 1000).rounded() / 1000
}

/// A colour as `video.chroma.key`: exactly three components, clamped to 0…1.
///
/// That key is the ONE colour in the schema the model spells without an alpha
/// (`[f64; 3]` in `model.rs`, and `props_check.rs` bounds each channel), so a
/// four-component `RGBA` — which is what a colour well hands back, and what
/// the comparison in `changedRGBA` needs — has to be cut back to three before
/// it can reach `set_video`. A longer array is not a warning there: serde
/// answers `invalid length 4, expected an array of length 3` and the whole
/// edit fails.
func chromaKeyComponents(_ color: RGBA) -> [Double] {
    (0..<3).map { index in
        let value = index < color.count ? color[index] : 0
        return canvasRound(min(max(value, 0), 1))
    }
}

// MARK: - Move

/// Dragging inside the box to move the selection (spec §4.2). Every selected
/// clip moves by the same canvas-space delta; the anchor clip's rectangle is
/// what snapping tests, so the whole selection clicks into place together.
///
/// The op writes the target's props plus the delta (the base, or the selected
/// action's end state — CI-13), never the evaluated position at the playhead.
struct CanvasMoveSession {
    /// The target's `(x, y)` per clip, captured at mouse-down.
    let bases: [UInt32: CGPoint]
    let anchor: UInt32
    /// The anchor's rotated bounds at mouse-down.
    let anchorBounds: CGRect
    /// Pointer position at mouse-down, canvas space.
    let grab: CGPoint

    var delta = CGVector.zero
